CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(320) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, display_name varchar(120) NOT NULL, avatar_url text, status varchar(30) NOT NULL DEFAULT 'ACTIVE', emergency_contact jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0);
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(30) NOT NULL UNIQUE);
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, PRIMARY KEY (user_id, role_id));
CREATE TABLE provinces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL UNIQUE, slug varchar(140) NOT NULL UNIQUE, region_code varchar(30));
CREATE TABLE destination_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL UNIQUE, icon varchar(100));
CREATE TABLE destinations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), province_id uuid NOT NULL REFERENCES provinces(id), category_id uuid NOT NULL REFERENCES destination_categories(id), name varchar(200) NOT NULL, slug varchar(220) NOT NULL UNIQUE, description text, latitude numeric(9,6), longitude numeric(9,6), price_min numeric(15,2), price_max numeric(15,2), opening_hours jsonb, status varchar(30) NOT NULL DEFAULT 'DRAFT', source_url text, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0, CHECK (price_min IS NULL OR price_min >= 0), CHECK (price_max IS NULL OR price_max >= price_min));
CREATE TABLE destination_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), destination_id uuid NOT NULL REFERENCES destinations(id) ON DELETE CASCADE, storage_path text NOT NULL, alt_text varchar(300), sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE favorites (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, destination_id uuid NOT NULL REFERENCES destinations(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, destination_id));
CREATE TABLE trips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), title varchar(200) NOT NULL, start_date date NOT NULL, end_date date NOT NULL, destination_summary text, budget_total numeric(15,2), currency char(3) NOT NULL DEFAULT 'VND', status varchar(30) NOT NULL DEFAULT 'PLANNING', visibility varchar(30) NOT NULL DEFAULT 'PRIVATE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0, CHECK (end_date >= start_date), CHECK (budget_total IS NULL OR budget_total >= 0));
CREATE TABLE trip_members (trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role varchar(20) NOT NULL, status varchar(20) NOT NULL, joined_at timestamptz, budget_share numeric(15,2), PRIMARY KEY (trip_id, user_id));
CREATE TABLE trip_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, invited_email varchar(320) NOT NULL, token_hash varchar(255) NOT NULL UNIQUE, status varchar(20) NOT NULL DEFAULT 'PENDING', expires_at timestamptz NOT NULL, invited_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE itinerary_days (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, day_number integer NOT NULL, trip_date date NOT NULL, UNIQUE (trip_id, day_number), UNIQUE (trip_id, trip_date));
CREATE TABLE itinerary_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), itinerary_day_id uuid NOT NULL REFERENCES itinerary_days(id) ON DELETE CASCADE, destination_id uuid REFERENCES destinations(id), custom_stop_name varchar(200), start_time time, end_time time, sort_order integer NOT NULL, note text, source varchar(30) NOT NULL DEFAULT 'MANUAL', updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0, CHECK (destination_id IS NOT NULL OR custom_stop_name IS NOT NULL));
CREATE TABLE destination_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, destination_id uuid REFERENCES destinations(id), proposed_by uuid NOT NULL REFERENCES users(id), title varchar(200), status varchar(20) NOT NULL DEFAULT 'OPEN', closes_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE destination_votes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proposal_id uuid NOT NULL REFERENCES destination_proposals(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, vote varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (proposal_id, user_id));
CREATE TABLE expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, title varchar(200) NOT NULL, amount numeric(15,2) NOT NULL CHECK (amount >= 0), currency char(3) NOT NULL DEFAULT 'VND', paid_by uuid NOT NULL REFERENCES users(id), category varchar(50), occurred_at timestamptz NOT NULL, status varchar(20) NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0);
CREATE TABLE expense_splits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_id uuid NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), share_amount numeric(15,2) NOT NULL CHECK (share_amount >= 0), settled_status varchar(20) NOT NULL DEFAULT 'UNSETTLED', UNIQUE (expense_id, user_id));
CREATE TABLE location_shares (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, enabled boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL, last_latitude numeric(9,6), last_longitude numeric(9,6), last_updated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (trip_id, user_id));
CREATE TABLE meetup_points (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, created_by uuid NOT NULL REFERENCES users(id), label varchar(200) NOT NULL, latitude numeric(9,6) NOT NULL, longitude numeric(9,6) NOT NULL, target_time timestamptz);
CREATE TABLE checkins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, itinerary_item_id uuid REFERENCES itinerary_items(id), user_id uuid NOT NULL REFERENCES users(id), checked_in_at timestamptz NOT NULL DEFAULT now(), latitude numeric(9,6), longitude numeric(9,6));
CREATE TABLE sos_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), latitude numeric(9,6), longitude numeric(9,6), location_timestamp timestamptz, message text, status varchar(20) NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), destination_id uuid REFERENCES destinations(id), body text NOT NULL, status varchar(20) NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0);
CREATE TABLE post_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE, storage_path text NOT NULL, media_type varchar(50) NOT NULL);
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), destination_id uuid NOT NULL REFERENCES destinations(id), rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5), body text, status varchar(20) NOT NULL DEFAULT 'VISIBLE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, destination_id));
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, status varchar(20) NOT NULL DEFAULT 'VISIBLE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES users(id), target_type varchar(30) NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, status varchar(20) NOT NULL DEFAULT 'OPEN', handled_by uuid REFERENCES users(id), handled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), target_type varchar(30) NOT NULL, target_id uuid NOT NULL, rule_score numeric(5,4), ai_score numeric(5,4), reasons_json jsonb, action varchar(30) NOT NULL, reviewer_id uuid REFERENCES users(id), previous_status varchar(30), next_status varchar(30), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type varchar(50) NOT NULL, payload_json jsonb NOT NULL DEFAULT '{}'::jsonb, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action varchar(80) NOT NULL, entity_type varchar(80) NOT NULL, entity_id uuid, metadata_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX idx_destinations_discovery ON destinations(status, province_id, category_id);
CREATE INDEX idx_destinations_name_lower ON destinations(lower(name));
CREATE INDEX idx_trip_members_user ON trip_members(user_id, status);
CREATE INDEX idx_notifications_unread ON notifications(user_id, created_at DESC) WHERE read_at IS NULL;
CREATE INDEX idx_content_reports_queue ON content_reports(status, created_at);
CREATE INDEX idx_location_shares_active ON location_shares(trip_id, expires_at) WHERE enabled = true;
INSERT INTO roles(code) VALUES ('USER'), ('MODERATOR'), ('ADMIN');
